    ('01A1A5AE-84E3-7420-AB77-FA435ADFEE81', 1002, N'SSDDD', N'Done', '135156CA-891F-44F8-8340-3F6BC58D515E', N'{"priority":"Medium","tags":[],"metadata":{}}', CONVERT(DATETIME2, '2026-11-04T08:30:40.3553813', 126), CONVERT(DATETIME2, '2026-11-04T13:30:29.4739415', 126)),
