-------------------------------------------------------------------------------
-- La numeración de tareas continúa después del mayor número.
-------------------------------------------------------------------------------
DECLARE @Next BIGINT = (SELECT ISNULL(MAX(Number), 0) + 1 FROM dbo.Tasks);
DECLARE @Sql NVARCHAR(200) = N'ALTER SEQUENCE dbo.TaskNumberSequence RESTART WITH ' + CAST(@Next AS NVARCHAR(20));
EXEC sys.sp_executesql @Sql;
GO

SELECT (SELECT COUNT(*) FROM dbo.Users) AS Users, (SELECT COUNT(*) FROM dbo.Tasks) AS Tasks,
       (SELECT COUNT(*) FROM dbo.UserPhotos) AS Photos;
